  <style>
    /* ===== RESET ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --orange: #FF7A00;
      --purple-light: #EDE4FF;
      --orange-light: #FFF0E0;
      --gray-50: #FAFAFA;
      --gray-100: #F5F5F5;
      --gray-200: #EEEEEE;
      --gray-300: #E0E0E0;
      --gray-400: #BDBDBD;
      --gray-500: #9E9E9E;
      --gray-600: #757575;
      --gray-700: #616161;
      --gray-800: #424242;
      --gray-900: #212121;
      --white: #FFFFFF;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--black);
      background: var(--white);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    ul, ol { list-style: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; font-family: inherit; }

    /* ===== UTILITY ===== */
    .container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }

    /* ===== HEADER ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .header-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 1.35rem;
      font-weight: 800;
      letter-spacing: -0.02em;
    }

    .header-logo-icon {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-weight: 900;
      font-size: 1.15rem;
    }

    .header-nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .header-nav a {
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--gray-800);
      transition: color 0.15s;
    }

    .header-nav a:hover { color: var(--purple); }

    .btn-login {
      padding: 9px 22px;
      border-radius: var(--radius-full);
      font-size: 0.875rem;
      font-weight: 600;
      border: 2px solid var(--gray-200);
      background: var(--white);
      color: var(--black);
      transition: all 0.15s;
    }

    .btn-login:hover {
      border-color: var(--purple);
      color: var(--purple);
    }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      padding: 8px;
      z-index: 200;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2.5px;
      background: var(--black);
      border-radius: 4px;
      transition: all 0.3s;
    }

    .hamburger.active span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 150;
      padding: 100px 32px 40px;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
    }

    .mobile-nav.active { display: flex; }

    .mobile-nav a {
      font-size: 1.5rem;
      font-weight: 700;
      padding: 16px 0;
      border-bottom: 1px solid var(--gray-100);
      letter-spacing: -0.01em;
    }

    .mobile-nav .btn-login {
      display: inline-flex;
      justify-content: center;
      margin-top: 20px;
      padding: 14px 28px;
      font-size: 1rem;
    }

    @media (max-width: 768px) {
      .header-nav { display: none; }
      .hamburger { display: flex; }
    }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      padding: 100px 0 120px;
      overflow: hidden;
      text-align: center;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      z-index: 0;
    }

    .hero-bg::before {
      content: '';
      position: absolute;
      top: -40%;
      left: -20%;
      width: 140%;
      height: 180%;
      background:
        radial-gradient(ellipse at 30% 20%, rgba(118,56,250,0.12) 0%, transparent 60%),
        radial-gradient(ellipse at 70% 60%, rgba(255,122,0,0.10) 0%, transparent 60%),
        radial-gradient(ellipse at 50% 80%, rgba(118,56,250,0.06) 0%, transparent 50%);
    }

    .hero-content {
      position: relative;
      z-index: 2;
      max-width: 780px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .hero h1 {
      font-size: clamp(2.5rem, 6vw, 4.25rem);
      font-weight: 900;
      letter-spacing: -0.03em;
      line-height: 1.08;
      margin-bottom: 24px;
      background: linear-gradient(135deg, var(--black) 30%, var(--purple));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: clamp(1.05rem, 2vw, 1.25rem);
      color: var(--gray-700);
      max-width: 560px;
      margin: 0 auto 40px;
      line-height: 1.6;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 15px 36px;
      border-radius: var(--radius-full);
      font-size: 1rem;
      font-weight: 700;
      border: none;
      background: linear-gradient(135deg, var(--purple), #8B5CF6);
      color: white;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 20px rgba(118,56,250,0.3);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(118,56,250,0.4);
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 18px;
      border-radius: var(--radius-full);
      background: var(--purple-light);
      color: var(--purple);
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 28px;
    }

    .hero-badge-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--purple);
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.5; transform: scale(1.3); }
    }

    /* ===== SECTION SHARED ===== */
    .section { padding: 100px 0; }

    .section-gray { background: var(--gray-50); }

    /* ===== FEATURES & SAFETY ===== */
    .split-section {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .split-section.reverse { direction: rtl; }
    .split-section.reverse > * { direction: ltr; }

    .split-visual {
      position: relative;
      aspect-ratio: 1 / 1;
      border-radius: var(--radius-xl);
      overflow: hidden;
    }

    .split-visual.features-visual {
      background: linear-gradient(160deg, #EDE4FF 0%, #F5F0FF 40%, #FFF0E0 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .split-visual.safety-visual {
      background: linear-gradient(160deg, #E8F5E9 0%, #E3F2FD 50%, #F3E5F5 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .split-visual.creators-visual {
      background: linear-gradient(160deg, #FFF0E0 0%, #EDE4FF 50%, #FFE0E8 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .visual-icon-set {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 16px;
      padding: 24px;
    }

    .visual-icon-card {
      background: rgba(255,255,255,0.85);
      backdrop-filter: blur(10px);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      text-align: center;
      box-shadow: var(--shadow-sm);
    }

    .visual-icon-card .icon {
      font-size: 2rem;
      margin-bottom: 8px;
    }

    .visual-icon-card .label {
      font-size: 0.8rem;
      font-weight: 600;
      color: var(--gray-700);
    }

    .split-text h2 {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.02em;
      line-height: 1.15;
      margin-bottom: 20px;
    }

    .split-text p {
      font-size: 1.05rem;
      color: var(--gray-700);
      line-height: 1.7;
      margin-bottom: 28px;
      max-width: 480px;
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--purple);
      transition: gap 0.2s;
    }

    .link-arrow:hover { gap: 10px; }
    .link-arrow.external::after { content: '↗'; font-size: 0.85em; }

    @media (max-width: 768px) {
      .split-section {
        grid-template-columns: 1fr;
        gap: 40px;
      }
      .split-section.reverse { direction: ltr; }
      .split-visual { aspect-ratio: 4 / 3; }
    }

    /* ===== TAGLINE BANNER ===== */
    .tagline-banner {
      background: linear-gradient(135deg, var(--purple), #8B5CF6, var(--orange));
      padding: 72px 0;
      text-align: center;
    }

    .tagline-banner p {
      font-size: clamp(1.5rem, 3.5vw, 2.25rem);
      font-weight: 800;
      color: white;
      letter-spacing: -0.02em;
    }

    /* ===== NEWS CAROUSEL ===== */
    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
    }

    .news-header .label {
      font-size: 0.85rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--purple);
      margin-bottom: 8px;
    }

    .news-header h2 {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.02em;
    }

    .carousel-wrapper {
      position: relative;
    }

    .carousel {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 8px;
    }

    .carousel::-webkit-scrollbar { display: none; }

    .news-card {
      flex: 0 0 340px;
      scroll-snap-align: start;
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .news-card-thumb {
      height: 200px;
      position: relative;
      overflow: hidden;
    }

    .news-card-thumb .thumb-bg {
      position: absolute;
      inset: 0;
    }

    .thumb-1 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
    .thumb-2 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
    .thumb-3 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
    .thumb-4 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); }

    .thumb-play {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 52px;
      height: 52px;
      border-radius: 50%;
      background: rgba(255,255,255,0.95);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      color: var(--black);
      box-shadow: var(--shadow-md);
    }

    .news-card-body {
      padding: 20px 22px;
    }

    .news-card-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 12px;
    }

    .tag-pill {
      padding: 4px 12px;
      border-radius: var(--radius-full);
      font-size: 0.72rem;
