    (function() {
      var hamburger = document.getElementById('hamburger');
      var mobileNav = document.getElementById('mobileNav');
      var mobileLinks = mobileNav.querySelectorAll('a, button');
      var body = document.body;

      function openMenu() {
        hamburger.classList.add('active');
        hamburger.setAttribute('aria-expanded', 'true');
        mobileNav.classList.add('active');
        body.style.overflow = 'hidden';
      }

      function closeMenu() {
        hamburger.classList.remove('active');
        hamburger.setAttribute('aria-expanded', 'false');
        mobileNav.classList.remove('active');
        body.style.overflow = '';
      }

      hamburger.addEventListener('click', function() {
        if (mobileNav.classList.contains('active')) {
          closeMenu();
        } else {
          openMenu();
        }
      });

      mobileLinks.forEach(function(link) {
        link.addEventListener('click', closeMenu);
      });

      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && mobileNav.classList.contains('active')) {
          closeMenu();
          hamburger.focus();
        }
      });
    })();

    /* ===== NEWS CAROUSEL ===== */
    (function() {
      var carousel = document.getElementById('newsCarousel');
      var scrollLeftBtn = document.getElementById('scrollLeft');
      var scrollRightBtn = document.getElementById('scrollRight');

      var scrollAmount = 360;

      function updateButtons() {
        if (!carousel) return;
        var tolerance = 2;
        scrollLeftBtn.style.opacity = carousel.scrollLeft <= tolerance ? '0.35' : '1';
        scrollLeftBtn.style.pointerEvents = carousel.scrollLeft <= tolerance ? 'none' : 'auto';
        var atEnd = carousel.scrollLeft + carousel.clientWidth >= carousel.scrollWidth - tolerance;
        scrollRightBtn.style.opacity = atEnd ? '0.35' : '1';
        scrollRightBtn.style.pointerEvents = atEnd ? 'none' : 'auto';
      }

      scrollLeftBtn.addEventListener('click', function() {
        carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      });

      scrollRightBtn.addEventListener('click', function() {
        carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });

      carousel.addEventListener('scroll', updateButtons);

      // Touch/swipe handling is native via scroll-snap + overflow-x: auto
      updateButtons();
      window.addEventListener('resize', updateButtons);
    })();
  </script>

